def first_match(scores, target):
    low, high, result = 0, len(scores) - 1, -1
    while low <= high:
        mid = (low + high) // 2
        if scores[mid] >= target:
            if scores[mid] == target:
                result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result
